@extends('admin.layout')@section('title','Enquiry Management')@section('content')<div class="panel"><form method="get"><input class="search" name="q" value="{{ request('q') }}" placeholder="Search by name, phone or course"><button class="btn" style="margin-top:8px">Search</button></form></div><div class="panel"><table><thead><tr><th>Student</th><th>Contact</th><th>Course</th><th>Message</th><th>Status</th><th>Action</th></tr></thead><tbody>@forelse($enquiries as $e)<tr><td><b>{{ $e->name }}</b><br><small>{{ $e->city }}</small></td><td><a href="tel:{{ $e->phone }}">{{ $e->phone }}</a><br><small>{{ $e->email }}</small></td><td>{{ $e->course_code }}</td><td>{{ $e->message }}</td><td><form method="post" action="{{ route('admin.enquiries.status',$e) }}">@csrf @method('PATCH')<select name="status" onchange="this.form.submit()">@foreach(['new','contacted','closed'] as $s)<option @selected($e->status===$s)>{{ $s }}</option>@endforeach</select></form></td><td><form method="post" action="{{ route('admin.enquiries.destroy',$e) }}" onsubmit="return confirm('Delete enquiry?')">@csrf @method('DELETE')<button class="btn btn-danger">Delete</button></form></td></tr>@empty<tr><td colspan="6">No enquiries found.</td></tr>@endforelse</tbody></table><div style="margin-top:16px">{{ $enquiries->links() }}</div></div>@endsection
